import{_ as a,o as n,c as t,a3 as p}from"./chunks/framework.Cc-oPviL.js";const u=JSON.parse('{"title":"00 · 一张图串起全部：一次请求的完整旅程","description":"","frontmatter":{},"headers":[],"relativePath":"bagu/summary/00.md","filePath":"bagu/summary/00.md"}'),l={name:"bagu/summary/00.md"};function e(i,s,o,c,d,r){return n(),t("div",null,[...s[0]||(s[0]=[p(`<h1 id="_00-·-一张图串起全部-一次请求的完整旅程" tabindex="-1">00 · 一张图串起全部：一次请求的完整旅程 <a class="header-anchor" href="#_00-·-一张图串起全部-一次请求的完整旅程" aria-label="Permalink to &quot;00 · 一张图串起全部：一次请求的完整旅程&quot;">​</a></h1><blockquote><p>这是全库的总纲。<strong>如果只能记一篇，记这篇。</strong> 它把四个模块（OS / 网络 / 数据结构 / 数据库）挂在同一条时间线上。</p></blockquote><h2 id="怎么用这篇" tabindex="-1">怎么用这篇 <a class="header-anchor" href="#怎么用这篇" aria-label="Permalink to &quot;怎么用这篇&quot;">​</a></h2><ol><li>先通读一遍，不求记住。</li><li>学完四个模块后回来，<strong>合上资料，自己画一遍</strong>。</li><li>画不出来的地方，就是还没真懂的模块。</li></ol><h2 id="总图-从敲下回车到页面出现" tabindex="-1">总图：从敲下回车到页面出现 <a class="header-anchor" href="#总图-从敲下回车到页面出现" aria-label="Permalink to &quot;总图：从敲下回车到页面出现&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[0] 你按下回车</span></span>
<span class="line"><span>     |</span></span>
<span class="line"><span>     v</span></span>
<span class="line"><span>+-- [1] 应用层（浏览器）</span></span>
<span class="line"><span>|     · 解析 URL：协议、域名、端口、路径</span></span>
<span class="line"><span>|     · 查缓存：强缓存命中就直接用，不发请求</span></span>
<span class="line"><span>|     · 查 DNS 缓存（浏览器 -&gt; 系统 -&gt; hosts）</span></span>
<span class="line"><span>|</span></span>
<span class="line"><span>+-- [2] DNS 解析                                    【网络 05】</span></span>
<span class="line"><span>|     本地 DNS -&gt; 根 -&gt; 顶级域 -&gt; 权威（迭代查询）</span></span>
<span class="line"><span>|     拿到 IP：93.184.216.34</span></span>
<span class="line"><span>|     走 UDP 53，因为报文小、要快</span></span>
<span class="line"><span>|</span></span>
<span class="line"><span>+-- [3] TCP 三次握手                                【网络 02】</span></span>
<span class="line"><span>|     SYN -&gt; SYN+ACK -&gt; ACK</span></span>
<span class="line"><span>|     内核协议栈完成，不经过应用</span></span>
<span class="line"><span>|     要分配 socket、进半连接队列 / 全连接队列</span></span>
<span class="line"><span>|     进程此时是&quot;阻塞&quot;或&quot;异步等待&quot;            【OS 01/04】</span></span>
<span class="line"><span>|</span></span>
<span class="line"><span>+-- [4] TLS 握手（HTTPS）                           【网络 04】</span></span>
<span class="line"><span>|     ClientHello -&gt; ServerHello + 证书 -&gt; 密钥交换</span></span>
<span class="line"><span>|     非对称协商密钥，对称加密传数据</span></span>
<span class="line"><span>|     证书链验证可能又是一次网络请求</span></span>
<span class="line"><span>|</span></span>
<span class="line"><span>+-- [5] 发 HTTP 请求                                【网络 04】</span></span>
<span class="line"><span>|     GET /index.html HTTP/1.1 + Host + Cookie</span></span>
<span class="line"><span>|</span></span>
<span class="line"><span>+-- [6] 封装：应用 -&gt; TCP -&gt; IP -&gt; 链路             【网络 01】</span></span>
<span class="line"><span>|     TCP 头：源端口、目的端口 443、序号、窗口</span></span>
<span class="line"><span>|     IP 头：源 IP、目的 IP、TTL=64</span></span>
<span class="line"><span>|     MAC 头：源 MAC、下一跳（网关）的 MAC</span></span>
<span class="line"><span>|     查路由表决定下一跳，查 ARP 拿网关 MAC      【网络 05】</span></span>
<span class="line"><span>|</span></span>
<span class="line"><span>+-- [7] 内核发送数据                                【OS 04】</span></span>
<span class="line"><span>|     应用调 write() -&gt; 系统调用（用户态转内核态）【OS 05】</span></span>
<span class="line"><span>|     数据从用户缓冲区拷到 socket 发送缓冲区</span></span>
<span class="line"><span>|     网卡 DMA 取走，发到链路上</span></span>
<span class="line"><span>|     大文件可能用零拷贝（sendfile）绕过用户态</span></span>
<span class="line"><span>|</span></span>
<span class="line"><span>+-- [8] 路由转发                                    【网络 01】</span></span>
<span class="line"><span>|     每跳：拆 MAC 头 -&gt; TTL 减 1 -&gt; 查路由表 -&gt; 重写 MAC 头</span></span>
<span class="line"><span>|     IP 头不变，MAC 每跳都变</span></span>
<span class="line"><span>|     丢包了 TCP 重传（超时 / 3 个重复 ACK）     【网络 03】</span></span>
<span class="line"><span>|     拥塞控制决定发多快（cwnd）</span></span>
<span class="line"><span>|</span></span>
<span class="line"><span>+-- [9] 服务端收包                                  【OS 04】</span></span>
<span class="line"><span>|     网卡中断 -&gt; 内核协议栈逐层解封装</span></span>
<span class="line"><span>|     数据进 socket 接收缓冲区</span></span>
<span class="line"><span>|     epoll 检测到可读 -&gt; 唤醒工作线程</span></span>
<span class="line"><span>|     应用 read() -&gt; 系统调用 -&gt; 拷到用户缓冲区</span></span>
<span class="line"><span>|</span></span>
<span class="line"><span>+-- [10] 查数据库                                   【数据库】</span></span>
<span class="line"><span>|     a. 连接池取连接（可能又要一次 TCP 握手）</span></span>
<span class="line"><span>|     b. 解析 SQL -&gt; 优化器选索引 -&gt; 执行计划  【数据库 05】</span></span>
<span class="line"><span>|     c. 走 B+ 树找数据                        【数据库 01】</span></span>
<span class="line"><span>|        Buffer Pool 命中 -&gt; 内存里直接返回     【OS 02/04】</span></span>
<span class="line"><span>|        未命中 -&gt; 从磁盘读 16KB 页（一次 IO）</span></span>
<span class="line"><span>|     d. 读操作：用 MVCC 判断版本可见性        【数据库 03】</span></span>
<span class="line"><span>|     e. 写操作：加锁 -&gt; 改 Buffer Pool -&gt; 写 undo</span></span>
<span class="line"><span>|               -&gt; 写 redo -&gt; 写 binlog -&gt; 两阶段提交 【数据库 02】</span></span>
<span class="line"><span>|        没走索引 -&gt; 锁全表 -&gt; 别人全等着       【数据库 04】</span></span>
<span class="line"><span>|</span></span>
<span class="line"><span>+-- [11] 返回响应                                   【网络 04】</span></span>
<span class="line"><span>|     200 OK + Cache-Control + ETag + HTML</span></span>
<span class="line"><span>|     原路返回（7~9 反过来走一遍）</span></span>
<span class="line"><span>|</span></span>
<span class="line"><span>+-- [12] 浏览器渲染</span></span>
<span class="line"><span>      HTML -&gt; DOM -&gt; CSSOM -&gt; 渲染树 -&gt; 布局 -&gt; 绘制</span></span>
<span class="line"><span>      发现 CSS/JS/图片 -&gt; 再发请求（复用连接）</span></span></code></pre></div><h2 id="四条横向对照-同一个概念在四个模块里的样子" tabindex="-1">四条横向对照：同一个概念在四个模块里的样子 <a class="header-anchor" href="#四条横向对照-同一个概念在四个模块里的样子" aria-label="Permalink to &quot;四条横向对照：同一个概念在四个模块里的样子&quot;">​</a></h2><p>这张表是全库最值钱的部分。<strong>面试时能把一个概念跨模块对照，就是&quot;真懂&quot;的信号</strong>。</p><table tabindex="0"><thead><tr><th>抽象概念</th><th>操作系统</th><th>计算机网络</th><th>数据结构</th><th>数据库</th></tr></thead><tbody><tr><td><strong>分层/封装</strong></td><td>用户态 / 内核态</td><td>TCP/IP 四层</td><td>—</td><td>存储引擎 / Server 层</td></tr><tr><td><strong>缓存</strong></td><td>CPU 缓存、TLB、页缓存</td><td>DNS 缓存、ARP 缓存、HTTP 缓存</td><td>—</td><td>Buffer Pool、查询缓存</td></tr><tr><td><strong>淘汰策略</strong></td><td>页面置换（Clock）</td><td>DNS TTL、ARP 超时</td><td>LRU 缓存</td><td>Buffer Pool 的改良 LRU</td></tr><tr><td><strong>队列</strong></td><td>就绪队列、阻塞队列</td><td>半连接队列、全连接队列</td><td>BFS、优先队列</td><td>锁等待队列</td></tr><tr><td><strong>锁</strong></td><td>互斥锁、自旋锁、读写锁</td><td>—</td><td>—</td><td>行锁、表锁、间隙锁</td></tr><tr><td><strong>死锁</strong></td><td>四条件 + 银行家算法</td><td>—</td><td>—</td><td>等待图检测 + 回滚</td></tr><tr><td><strong>多版本/乐观</strong></td><td>COW（写时复制）</td><td>—</td><td>持久化数据结构</td><td>MVCC</td></tr><tr><td><strong>索引</strong></td><td>页表（虚拟&gt;物理）</td><td>路由表（目的&gt;下一跳）</td><td>B+ 树、哈希表</td><td>B+ 树索引</td></tr><tr><td><strong>分片/局部性</strong></td><td>分页、NUMA</td><td>子网、CDN 就近</td><td>数组 vs 链表（缓存行）</td><td>分库分表、分区表</td></tr><tr><td><strong>日志/重放</strong></td><td>journal（文件系统）</td><td>—</td><td>—</td><td>redo log、binlog</td></tr><tr><td><strong>地址翻译</strong></td><td>虚拟地址 &gt; 物理地址</td><td>域名 &gt; IP &gt; MAC</td><td>—</td><td>逻辑行 &gt; 页 &gt; 磁盘偏移</td></tr></tbody></table><p><strong>怎么用这张表</strong>：随便挑一行，试着讲清&quot;这四列分别是什么、为什么这么像&quot;。讲得通，说明你的知识是网状的。</p><h2 id="三个-横切问题-一个现象牵出四个模块" tabindex="-1">三个&quot;横切问题&quot;：一个现象牵出四个模块 <a class="header-anchor" href="#三个-横切问题-一个现象牵出四个模块" aria-label="Permalink to &quot;三个&quot;横切问题&quot;：一个现象牵出四个模块&quot;">​</a></h2><h3 id="问题-1-我的程序为什么卡住了" tabindex="-1">问题 1：我的程序为什么卡住了？ <a class="header-anchor" href="#问题-1-我的程序为什么卡住了" aria-label="Permalink to &quot;问题 1：我的程序为什么卡住了？&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>程序卡住</span></span>
<span class="line"><span>+- 在等 CPU？        &gt; 就绪队列太长，负载过高            【OS 调度】</span></span>
<span class="line"><span>+- 在等锁？          &gt; 互斥锁/自旋锁，或者数据库行锁      【OS 并发 / 数据库锁】</span></span>
<span class="line"><span>+- 在等 IO？         &gt; 阻塞 IO，对端没回，磁盘慢          【OS IO / 网络】</span></span>
<span class="line"><span>+- 在等数据库？      &gt; 慢 SQL、锁等待、连接池打满         【数据库】</span></span>
<span class="line"><span>+- 在等 GC？         &gt; 内存不够，频繁回收                 【语言运行时】</span></span>
<span class="line"><span>+- 在等网络？        &gt; RTT 大、丢包重传、拥塞窗口太小      【网络】</span></span></code></pre></div><p><strong>排查顺序</strong>：先看 CPU 使用率（高 &gt; 计算密集/自旋；低 &gt; 在等）&gt; 看线程栈（在哪一行阻塞）&gt; 看数据库慢查询 &gt; 看网络 RTT。</p><h3 id="问题-2-为什么我的接口-p99-是-2-秒-但平均只有-50ms" tabindex="-1">问题 2：为什么我的接口 P99 是 2 秒，但平均只有 50ms？ <a class="header-anchor" href="#问题-2-为什么我的接口-p99-是-2-秒-但平均只有-50ms" aria-label="Permalink to &quot;问题 2：为什么我的接口 P99 是 2 秒，但平均只有 50ms？&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>P99 远高于平均值 = 有&quot;长尾&quot;</span></span>
<span class="line"><span>长尾的常见来源：</span></span>
<span class="line"><span>+- 缓存击穿/雪崩         &gt; 少量请求打到数据库          【数据库 + 缓存】</span></span>
<span class="line"><span>+- 锁等待               &gt; 少数请求排队                  【OS / 数据库】</span></span>
<span class="line"><span>+- 慢 SQL               &gt; 个别查询没走索引              【数据库】</span></span>
<span class="line"><span>+- GC 停顿              &gt; 周期性 STW                   【语言运行时】</span></span>
<span class="line"><span>+- TCP 重传             &gt; 丢包导致等待 RTO（几百 ms）   【网络】</span></span>
<span class="line"><span>+- 连接池耗尽           &gt; 请求排队等连接                【数据库 + 网络】</span></span></code></pre></div><p><strong>关键</strong>：<strong>平均值会掩盖长尾</strong>。优化 P99 往往比优化平均值更有价值。</p><h3 id="问题-3-系统能扛多少并发" tabindex="-1">问题 3：系统能扛多少并发？ <a class="header-anchor" href="#问题-3-系统能扛多少并发" aria-label="Permalink to &quot;问题 3：系统能扛多少并发？&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>并发能力 = 最窄的那个瓶颈</span></span>
<span class="line"><span></span></span>
<span class="line"><span>① CPU 够吗？        &gt; 计算密集型的上限 = 核数          【OS】</span></span>
<span class="line"><span>② 内存够吗？        &gt; Buffer Pool / 缓存 / 线程栈        【OS】</span></span>
<span class="line"><span>③ 连接数够吗？      &gt; 文件描述符、端口数、连接池大小      【OS / 网络】</span></span>
<span class="line"><span>④ 数据库扛得住吗？  &gt; QPS、锁竞争、连接数                【数据库】</span></span>
<span class="line"><span>⑤ 带宽够吗？        &gt; 出口带宽 / 每请求大小              【网络】</span></span>
<span class="line"><span>⑥ 有没有串行点？    &gt; 全局锁、单点写入、自增 ID           【全模块】</span></span></code></pre></div><p><strong>&quot;能扛多少并发&quot;这个问题，答案永远是&quot;最窄的那一环&quot;</strong>。找到它，比盲目扩容有用得多。</p><h2 id="一张极简版总图-贴在墙上那种" tabindex="-1">一张极简版总图（贴在墙上那种） <a class="header-anchor" href="#一张极简版总图-贴在墙上那种" aria-label="Permalink to &quot;一张极简版总图（贴在墙上那种）&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户</span></span>
<span class="line"><span> |</span></span>
<span class="line"><span> v</span></span>
<span class="line"><span>浏览器 -------- DNS 查 IP -------------------- 【网络 05】</span></span>
<span class="line"><span> |</span></span>
<span class="line"><span> |  TCP 握手 / TLS 握手 --------------------- 【网络 02/04】</span></span>
<span class="line"><span> v</span></span>
<span class="line"><span>内核协议栈 ---- 封装 / 解封装 ---------------- 【网络 01】</span></span>
<span class="line"><span> |</span></span>
<span class="line"><span> |  socket 缓冲区 + epoll ------------------- 【OS 04】</span></span>
<span class="line"><span> v</span></span>
<span class="line"><span>应用进程 ------ 线程调度 / 锁 ----------------- 【OS 01/03】</span></span>
<span class="line"><span> |</span></span>
<span class="line"><span> |  SQL</span></span>
<span class="line"><span> v</span></span>
<span class="line"><span>数据库 -------- 优化器 -&gt; B+ 树 -&gt; Buffer Pool - 【数据库 01/05】</span></span>
<span class="line"><span> |             事务 / MVCC / 锁 --------------- 【数据库 02/03/04】</span></span>
<span class="line"><span> |  缺页 / 刷盘</span></span>
<span class="line"><span> v</span></span>
<span class="line"><span>磁盘 ---------- 虚拟内存 / 页缓存 ------------- 【OS 02】</span></span></code></pre></div><h2 id="和其他知识的连接" tabindex="-1">和其他知识的连接 <a class="header-anchor" href="#和其他知识的连接" aria-label="Permalink to &quot;和其他知识的连接&quot;">​</a></h2><ul><li>这篇是 <code>00-导读</code> 各模块地图的&quot;总装&quot;</li><li>所有细节都在 <code>01-操作系统/</code>、<code>02-计算机网络/</code>、<code>03-数据结构与算法/</code>、<code>04-数据库原理/</code> 里</li></ul><h2 id="自测-3-问" tabindex="-1">自测 3 问 <a class="header-anchor" href="#自测-3-问" aria-label="Permalink to &quot;自测 3 问&quot;">​</a></h2><p><strong>Q1：不看资料，把&quot;输入 URL 到页面出现&quot;讲一遍，能讲到几层？</strong></p><details class="details custom-block"><summary>点开看答案</summary><p><strong>能讲到 8 层以上算过关</strong>，关键节点： DNS &gt; TCP 握手 &gt; TLS 握手 &gt; 发 HTTP &gt; 封装 &gt; 路由转发 &gt; 服务端收包 &gt; 查数据库 &gt; 返回 &gt; 渲染。</p><p><strong>加分点</strong>：</p><ul><li>每一步能说出&quot;属于哪个模块&quot;</li><li>能说出&quot;这一步如果失败，会看到什么现象&quot;（比如 DNS 失败 &gt; 域名解析错误；TCP 失败 &gt; 连接超时）</li></ul><p><strong>减分点</strong>：</p><ul><li>只会说&quot;发请求、收响应&quot;，中间全是黑的</li><li>说不清封装/解封装</li></ul></details><p><strong>Q2：为什么&quot;能扛多少并发&quot;的答案永远是&quot;最窄的那一环&quot;？</strong></p><details class="details custom-block"><summary>点开看答案</summary><p>因为系统是<strong>串行依赖</strong>的：请求必须依次经过 CPU、内存、网络、数据库。</p><p>木桶效应：整个系统的吞吐量 = 所有环节里<strong>最小的那个</strong>。</p><p>举例：</p><ul><li>应用层能处理 10 万 QPS，但数据库只能 5000 QPS &gt; 系统上限 5000。</li><li>数据库能 5 万 QPS，但出口带宽只够 1 万请求 &gt; 上限 1 万。</li><li>都够，但有个全局锁 &gt; 上限就是锁的吞吐。</li></ul><p><strong>所以扩容不能盲目</strong>：加机器但数据库是瓶颈，只会让数据库更早崩。<strong>先找到瓶颈，再针对性优化</strong>。</p></details><p><strong>Q3：为什么说&quot;P99 比平均值更值得优化&quot;？</strong></p><details class="details custom-block"><summary>点开看答案</summary><p>因为<strong>用户感知的是最慢的那部分</strong>。</p><p>假设 100 个请求：99 个 50ms，1 个 2 秒。</p><ul><li>平均值 = 69.5ms，看起来很好。</li><li>但那个 2 秒的请求，用户会明显感觉&quot;卡了&quot;。</li></ul><p>而且长尾往往有<strong>系统性原因</strong>（锁等待、GC、丢包重传、缓存击穿），不是随机的。不解决，它会周期性出现，且随流量增长而恶化。</p><p><strong>工程实践</strong>：监控要看 P95 / P99 / P999，而不是只看平均值。平均值会掩盖问题。</p></details><h2 id="类比失效处-易错点" tabindex="-1">类比失效处 / 易错点 <a class="header-anchor" href="#类比失效处-易错点" aria-label="Permalink to &quot;类比失效处 / 易错点&quot;">​</a></h2><ul><li><strong>&quot;一条流水线&quot;类比会让人以为请求是严格串行的</strong>。实际上服务端有连接池、线程池，多个请求是并发处理的，图里画的是&quot;单个请求的路径&quot;。</li><li><strong>不要以为&quot;图里的顺序&quot;就是&quot;真实的时序&quot;</strong>。比如 TLS 握手和 DNS 查询可能并行（HTTP/3 甚至合并），浏览器会预连接、预解析。</li><li><strong>&quot;四层对照表&quot;不是严格对应</strong>。比如&quot;锁&quot;在网络层就没有对应物——不要为了凑对称硬编。</li><li><strong>这张图是&quot;典型路径&quot;</strong>，不是&quot;所有路径&quot;。有 CDN 时请求可能根本不打到源站；有缓存时可能不查数据库。</li><li><strong>能背图 ≠ 懂原理</strong>。图是索引，真正的理解在每个模块的&quot;为什么这么设计&quot;里。</li></ul><h2 id="✅-验收清单" tabindex="-1">✅ 验收清单 <a class="header-anchor" href="#✅-验收清单" aria-label="Permalink to &quot;✅ 验收清单&quot;">​</a></h2><ul><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="0"> 能合上资料，自己画出这张总图（至少 8 个节点，标出所属模块）</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="1"> 能口述&quot;输入 URL 到页面出现&quot;，每个环节说出&quot;属于哪个模块、关键机制是什么&quot;</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="2"> 能挑&quot;四层对照表&quot;里任意 3 行，讲清四列的对应关系</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="3"> 能用&quot;程序卡住了&quot;这个问题，牵出至少 4 个模块的原因</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="4"> 能解释&quot;为什么 P99 比平均值更值得关注&quot;</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="5"> 能解释&quot;系统并发上限 = 最窄的一环&quot;，并举一个具体例子</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="6"> 能画出极简版总图（浏览器 &gt; 协议栈 &gt; 进程 &gt; 数据库 &gt; 磁盘）</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="7"> 合上书，用自己的话讲 5 分钟，中途不卡壳</li></ul>`,35)])])}const h=a(l,[["render",e]]);export{u as __pageData,h as default};
